def _replace(check):
    name = os.getenv('AI_POSTGRES_SCHEMA', 'qq_bot').strip() or 'qq_bot'
    if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', name):
        raise RuntimeError('invalid_migration_schema')
    op.execute(sa.text('SET LOCAL search_path TO "'+name+'",public'))
    op.execute(sa.text('ALTER TABLE delivery_attempts DROP CONSTRAINT ck_delivery_attempts_official_fields'))
    op.execute(sa.text('ALTER TABLE delivery_attempts ADD CONSTRAINT ck_delivery_attempts_official_fields '+check))

def upgrade():
    _replace(CURRENT)

def downgrade():
    # History with memory-only windows cannot be represented by the old schema.
    raise RuntimeError('simple_sender_history_requires_export_before_downgrade')
